const { Client } = require('pg');
const https = require('https');

const connectionString = process.env.DATABASE_URL;
const clientId = process.env.GOOGLE_DRIVE_CLIENT_ID;
const clientSecret = process.env.GOOGLE_DRIVE_CLIENT_SECRET;
const refreshToken = process.env.GOOGLE_DRIVE_REFRESH_TOKEN;

function postForm(url, params) {
  return new Promise((resolve, reject) => {
    const urlObj = new URL(url);
    const body = Object.keys(params)
      .map(k => encodeURIComponent(k) + '=' + encodeURIComponent(params[k]))
      .join('&');
    const options = {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Content-Length': Buffer.byteLength(body)
      }
    };
    const req = https.request(urlObj, options, (res) => {
      let responseBody = '';
      res.on('data', chunk => responseBody += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(responseBody)); } catch (e) { reject(e); }
      });
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

function getJson(url, headers = {}) {
  return new Promise((resolve, reject) => {
    const options = { method: 'GET', headers };
    const req = https.request(url, options, (res) => {
      let responseBody = '';
      res.on('data', chunk => responseBody += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(responseBody)); } catch (e) { reject(e); }
      });
    });
    req.on('error', reject);
    req.end();
  });
}

async function main() {
  if (!connectionString) throw new Error('Missing DATABASE_URL env variable');
  if (!clientId || !clientSecret || !refreshToken) throw new Error('Missing Google Drive OAuth credentials');

  const tokenRes = await postForm('https://oauth2.googleapis.com/token', {
    client_id: clientId,
    client_secret: clientSecret,
    refresh_token: refreshToken,
    grant_type: 'refresh_token'
  });
  const accessToken = tokenRes.access_token;
  if (!accessToken) throw new Error('Failed to obtain Google access token');

  const pgClient = new Client({
    connectionString,
    ssl: { rejectUnauthorized: false }
  });
  await pgClient.connect();

  try {
    const todayDate = new Date().toISOString().split('T')[0];
    const plansRes = await pgClient.query('SELECT * FROM daily_content_plans WHERE plan_date = $1', [todayDate]);
    const plans = plansRes.rows;
    const upserted = [];

    for (const plan of plans) {
      let fileId = null;
      let status = 'NO_ASSET_REQUESTED';
      let reason = 'No asset requested for this slot.';
      const assetRef = plan.content_asset_ref;

      if (assetRef) {
        try {
          const q = 'name=\'' + assetRef.replace(/'/g, '\\\'') + '\' and trashed=false';
          const url = 'https://www.googleapis.com/drive/v3/files?q=' + encodeURIComponent(q) + '&fields=files(id,name)';
          const driveRes = await getJson(url, { 'Authorization': 'Bearer ' + accessToken });
          const files = driveRes.files || [];

          if (files.length === 0) {
            status = 'MISSING_ASSET';
            reason = 'File was not found in Google Drive.';
          } else if (files.length === 1) {
            fileId = files[0].id;
            status = 'RESOLVED';
            reason = 'Found exactly one matching file.';
          } else {
            status = 'AMBIGUOUS_ASSET';
            reason = 'Found ' + files.length + ' duplicate files with name "' + assetRef + '" on Google Drive.';
          }
        } catch (err) {
          status = 'ERROR';
          reason = 'Google API Error: ' + err.message;
        }
      }

      const upsertSql = 'INSERT INTO file_id_resolutions (plan_id, content_plan_id, content_asset_ref, google_drive_file_id, resolution_status, resolution_reason, resolved_at) VALUES ($1, $2, $3, $4, $5, $6, now()) ON CONFLICT (plan_id, content_plan_id) DO UPDATE SET content_asset_ref = EXCLUDED.content_asset_ref, google_drive_file_id = EXCLUDED.google_drive_file_id, resolution_status = EXCLUDED.resolution_status, resolution_reason = EXCLUDED.resolution_reason, resolved_at = now() RETURNING id;';

      const dbRes = await pgClient.query(upsertSql, [
        plan.id,
        plan.content_plan_id,
        assetRef,
        fileId,
        status,
        reason
      ]);

      upserted.push({ slotId: plan.content_plan_id, status, fileId });
    }

    await pgClient.end();
    return [{ json: { success: true, count: upserted.length, resolutions: upserted } }];
  } catch (err) {
    await pgClient.end();
    throw err;
  }
}
